      "implementationCpp": "// Prim's Minimum Spanning Tree O(E log V)\n#include <vector>\n#include <queue>\nusing namespace std;\n\nstruct Edge { int to, weight; };\n\nint primMST(int start, const vector<vector<Edge>>& adj) {\n    int n = adj.size(), mstCost = 0;\n    vector<bool> inMST(n, false);\n    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;\n    pq.push({0, start});\n    while (!pq.empty()) {\n        auto [w, u] = pq.top(); pq.pop();\n        if (inMST[u]) continue;\n        inMST[u] = true;\n        mstCost += w;\n        for (const auto& edge : adj[u]) {\n            if (!inMST[edge.to]) pq.push({edge.weight, edge.to});\n        }\n    }\n    return mstCost;\n}",
