  "slug": "busy-database",
    "title": "Busy Database",
    "tagline": "Avoid business calculations inside database layers, optimize triggers, and scale application layers.",
    "category": "System Design & Distributed Systems",
    "readTime": 20,
    "lastUpdated": "July 2026",
    "prerequisites": [],
