  "slug": "claim-check",
    "title": "Claim Check Pattern",
    "tagline": "Offload large message payloads, generate reference tokens, and optimize queue storage.",
    "category": "Cloud Design Patterns",
    "readTime": 20,
    "lastUpdated": "July 2026",
    "prerequisites": [],
    "related": [
      "message-queues",
      "static-content-hosting-data"
    ],
