  "slug": "supernetting",
    "title": "Supernetting: Route Summarization",
    "tagline": "Combine contiguous subnets into aggregate routing advertisements to shrink routing tables.",
    "category": "Network Engineering",
    "readTime": 10,
    "lastUpdated": "July 2026",
