  "slug": "compose-textfield",
    "title": "TextField & Input States",
    "tagline": "Configure editable inputs, manage state hoisting loops, and customize soft keyboards.",
    "category": "Android Development",
    "readTime": 11,
    "lastUpdated": "July 2026",
    "prerequisites": [
      "compose-text"
    ],
    "related": [
      "compose-button"
    ],
