    "title": "Compose UI Testing",
    "tagline": "Configure Compose UI test rules, traverse semantic trees, and assert Composable states.",
    "category": "Android Development",
    "readTime": 10,
    "lastUpdated": "July 2026",
    "prerequisites": [
      "compose-textfield"
    ],
